def _levenshtein(source: str, target: str) -> int:
    """Compute Levenshtein distance with the Wagner-Fischer algorithm."""

    source_range = range(len(source) + 1)
    target_range = range(len(target) + 1)
    matrix = [[i if j == 0 else j for j in target_range] for i in source_range]
    for i in source_range[1:]:
        for j in target_range[1:]:
            delete_cost = matrix[i - 1][j] + 1
            insert_cost = matrix[i][j - 1] + 1
            substitute_cost = matrix[i - 1][j - 1] + (
                0 if source[i - 1] == target[j - 1] else 1
            )
            matrix[i][j] = min(delete_cost, insert_cost, substitute_cost)
    return matrix[len(source)][len(target)]


def _levenshtein_norm(source: str, target: str) -> float:
    """Return the normalized Levenshtein distance in the range [0, 1]."""

    longest = max(len(source), len(target))
    if longest == 0:
        return 0.0
    return float(_levenshtein(source, target)) / longest


